use analysis::{scan,scan_with_progress,ScanOptions};
use std::{fs,sync::atomic::AtomicBool};
#[test]fn serial_parallel_equivalence(){let t=tempfile::tempdir().unwrap();for n in 0..64{fs::write(t.path().join(format!("{n}.wave")),"// comment\nfun main() {}\n\n").unwrap();}let a=scan(t.path(),&ScanOptions{threads:1,..ScanOptions::default()},&AtomicBool::new(false)).unwrap();let b=scan(t.path(),&ScanOptions{threads:4,..ScanOptions::default()},&AtomicBool::new(false)).unwrap();assert_eq!(a.totals(),b.totals());assert_eq!(b.totals().files,64);assert_eq!(b.languages[0].language,"Wave");assert_eq!(b.totals().unclassified,0);}
#[test]fn warm_refresh_reuses_only_unchanged_records(){let t=tempfile::tempdir().unwrap();let p=t.path().join("x.rs");fs::write(&p,"let x=1;\n").unwrap();let a=scan(t.path(),&ScanOptions::default(),&AtomicBool::new(false)).unwrap();let b=scan_with_progress(t.path(),&ScanOptions::default(),&AtomicBool::new(false),Some(&a),|_|{}).unwrap();assert_eq!(b.report.reused_files,1);fs::write(&p,"// different content and length\n\n").unwrap();let c=scan_with_progress(t.path(),&ScanOptions::default(),&AtomicBool::new(false),Some(&b),|_|{}).unwrap();assert_eq!(c.report.reused_files,0);assert_eq!(c.totals().comments,1);}
#[test]fn hundred_thousand_lines_do_not_allocate_prepared_source(){let t=tempfile::tempdir().unwrap();let text="fn long_named_function() { let value=123; } // source on demand\n".repeat(10000);for n in 0..10{fs::write(t.path().join(format!("{n}.rs")),&text).unwrap();}let a=scan(t.path(),&ScanOptions::default(),&AtomicBool::new(false)).unwrap();assert_eq!(a.totals().lines,100000);assert!(a.source_memory_bytes<650000);}
